    bronze_glassengravingdiamondpoint = { name = "Bronast diamantna konica za rezbarjenje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast diamantna konica za rezbarjenje za steklarje." },
    silver_glassengravingdiamondpoint = { name = "Srebrn diamantna konica za rezbarjenje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn diamantna konica za rezbarjenje za steklarje." },
    gilded_glassengravingdiamondpoint = { name = "Pozlačen diamantna konica za rezbarjenje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen diamantna konica za rezbarjenje za steklarje." },
    jewel_set_glassengravingdiamondpoint = { name = "Draguljast diamantna konica za rezbarjenje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast diamantna konica za rezbarjenje za steklarje." },
    royal_sovereign_glassengravingdiamondpoint = { name = "Kraljevski suveren diamantna konica za rezbarjenje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren diamantna konica za rezbarjenje z biseri za krono." },
