    glassengravingdiamondpoint_workshop = { name = "Glassengravingdiamondpoint delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glassengravingdiamondpoint_house = { name = "Glassengravingdiamondpoint hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassengravingdiamondpoint_atelier = { name = "Mojstrski glassengravingdiamondpoint atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassengravingdiamondpoint_palace = { name = "Suverena glassengravingdiamondpoint palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassEngravingDiamondPointMaker.ironStock=14; GlassEngravingDiamondPointMaker.bronzeStock=12; GlassEngravingDiamondPointMaker.woodStock=12; GlassEngravingDiamondPointMaker.leatherStock=8; GlassEngravingDiamondPointMaker.silverStock=8; GlassEngravingDiamondPointMaker.goldStock=6; GlassEngravingDiamondPointMaker.jewelStock=4; GlassEngravingDiamondPointMaker.pearlStock=4
GlassEngravingDiamondPointMaker.productStock = {}; GlassEngravingDiamondPointMaker.buildings = {}; GlassEngravingDiamondPointMaker.maker = nil; GlassEngravingDiamondPointMaker.activeMaking = {}; GlassEngravingDiamondPointMaker.totalProducts = 0; GlassEngravingDiamondPointMaker.dayTimer = 0
function GlassEngravingDiamondPointMaker.init() GlassEngravingDiamondPointMaker.ironStock=14; GlassEngravingDiamondPointMaker.bronzeStock=12; GlassEngravingDiamondPointMaker.woodStock=12; GlassEngravingDiamondPointMaker.leatherStock=8; GlassEngravingDiamondPointMaker.silverStock=8; GlassEngravingDiamondPointMaker.goldStock=6; GlassEngravingDiamondPointMaker.jewelStock=4; GlassEngravingDiamondPointMaker.pearlStock=4; GlassEngravingDiamondPointMaker.productStock={}; GlassEngravingDiamondPointMaker.buildings={}; GlassEngravingDiamondPointMaker.maker=nil; GlassEngravingDiamondPointMaker.activeMaking={}; GlassEngravingDiamondPointMaker.totalProducts=0; GlassEngravingDiamondPointMaker.dayTimer=0; print("[GlassEngravingDiamondPointMaker] Royal Glass Engraving Diamond Point Maker System initialized (6 products, 4 buildings)") end
function GlassEngravingDiamondPointMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassEngravingDiamondPointMaker.maker={name=n or ("Diamantar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Diamantar najet: %s (spretnost: %d)",GlassEngravingDiamondPointMaker.maker.name,s),"success") end; return true end
function GlassEngravingDiamondPointMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassEngravingDiamondPointMaker.build(id) local ok,e=GlassEngravingDiamondPointMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassEngravingDiamondPointMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassEngravingDiamondPointMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassEngravingDiamondPointMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassEngravingDiamondPointMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassEngravingDiamondPointMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassEngravingDiamondPointMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassEngravingDiamondPointMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassEngravingDiamondPointMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassEngravingDiamondPointMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassEngravingDiamondPointMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassEngravingDiamondPointMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassEngravingDiamondPointMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassEngravingDiamondPointMaker.buildings==0 then return false,"Potrebna diamantna delavnica" end; if not GlassEngravingDiamondPointMaker.maker then return false,"Potreben diamantar" end; return true end
function GlassEngravingDiamondPointMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassEngravingDiamondPointMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassEngravingDiamondPointMaker.ironStock=GlassEngravingDiamondPointMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassEngravingDiamondPointMaker.bronzeStock=GlassEngravingDiamondPointMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassEngravingDiamondPointMaker.woodStock=GlassEngravingDiamondPointMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassEngravingDiamondPointMaker.leatherStock=GlassEngravingDiamondPointMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassEngravingDiamondPointMaker.silverStock=GlassEngravingDiamondPointMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassEngravingDiamondPointMaker.goldStock=GlassEngravingDiamondPointMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassEngravingDiamondPointMaker.jewelStock=GlassEngravingDiamondPointMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassEngravingDiamondPointMaker.pearlStock=GlassEngravingDiamondPointMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassEngravingDiamondPointMaker.maker then t=math.max(1,t-math.floor(GlassEngravingDiamondPointMaker.maker.skill/13)) end; table.insert(GlassEngravingDiamondPointMaker.activeMaking,{id="glassengravingdiamondpoint_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassEngravingDiamondPointMaker.completeMaking(m) local q=1.0+(GlassEngravingDiamondPointMaker.getQualityBonus()/100); if GlassEngravingDiamondPointMaker.maker then q=q+(GlassEngravingDiamondPointMaker.maker.skill/140) end; q=math.min(2.5,q); GlassEngravingDiamondPointMaker.productStock[m.productType]=(GlassEngravingDiamondPointMaker.productStock[m.productType] or 0)+m.quantity; GlassEngravingDiamondPointMaker.totalProducts=GlassEngravingDiamondPointMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassEngravingDiamondPointMaker.maker then GlassEngravingDiamondPointMaker.maker.itemsMade=GlassEngravingDiamondPointMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassEngravingDiamondPointMaker.maker.skill=math.min(100,GlassEngravingDiamondPointMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Diamant izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassengravingdiamondpoint.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassEngravingDiamondPointMaker.update(dt) if not _G.state then return end; GlassEngravingDiamondPointMaker.dayTimer=GlassEngravingDiamondPointMaker.dayTimer+dt; if GlassEngravingDiamondPointMaker.dayTimer>=30 then GlassEngravingDiamondPointMaker.dayTimer=0; for i=#GlassEngravingDiamondPointMaker.activeMaking,1,-1 do local m=GlassEngravingDiamondPointMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassEngravingDiamondPointMaker.completeMaking(m); table.remove(GlassEngravingDiamondPointMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassEngravingDiamondPointMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassEngravingDiamondPointMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassEngravingDiamondPointMaker.getStats() return {ironStock=GlassEngravingDiamondPointMaker.ironStock,bronzeStock=GlassEngravingDiamondPointMaker.bronzeStock,woodStock=GlassEngravingDiamondPointMaker.woodStock,leatherStock=GlassEngravingDiamondPointMaker.leatherStock,silverStock=GlassEngravingDiamondPointMaker.silverStock,goldStock=GlassEngravingDiamondPointMaker.goldStock,jewelStock=GlassEngravingDiamondPointMaker.jewelStock,pearlStock=GlassEngravingDiamondPointMaker.pearlStock,productStock=GlassEngravingDiamondPointMaker.productStock,numBuildings=#GlassEngravingDiamondPointMaker.buildings,hasMaker=GlassEngravingDiamondPointMaker.maker~=nil,makerName=GlassEngravingDiamondPointMaker.maker and GlassEngravingDiamondPointMaker.maker.name or "—",makerSkill=GlassEngravingDiamondPointMaker.maker and GlassEngravingDiamondPointMaker.maker.skill or 0,activeMaking=#GlassEngravingDiamondPointMaker.activeMaking,totalProducts=GlassEngravingDiamondPointMaker.totalProducts} end
return GlassEngravingDiamondPointMaker
